import{_ as p,a0 as t,w as o,s as h,ao as r,I as l,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux Shell 编程中定义和使用函数 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux Shell 编程中定义和使用函数 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux Shell 编程中定义和使用函数 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux Shell 编程中定义和使用函数 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180819 How to define and use functions in Linux Shell Script","title":"如何在 Linux Shell 编程中定义和使用函数","tag":"201808","desc":""},"relativePath":"201808/20180819 How to define and use functions in Linux Shell Script.md","filePath":"[post].md"}'),d={name:"201808/20180819 How to define and use functions in Linux Shell Script.md"};function c(g,s,u,k,b,f){const n=t("Link");return o(),h("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-shell-编程中定义和使用函数" tabindex="-1">如何在 Linux Shell 编程中定义和使用函数 <a class="header-anchor" href="#如何在-linux-shell-编程中定义和使用函数" aria-label="Permalink to “如何在 Linux Shell 编程中定义和使用函数”">​</a></h1><p>函数是一段可复用的代码。我们通常把重复的代码放进函数中并且在不同的地方去调用它。库是函数的集合。我们可以在库中定义经常使用的函数，这样其它脚本便可以不再重复代码而使用这些函数。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/08/Functions-Linux-Shell-Script.jpg" alt="Functions-Linux-Shell-Script"></p><p>本文我们将讨论诸多关于函数的内容和一些使用技巧。为了方便演示，我将在 Ubuntu 系统上使用 <strong>Bourne Again SHell (Bash)</strong>。</p><h3 id="调用函数" tabindex="-1">调用函数 <a class="header-anchor" href="#调用函数" aria-label="Permalink to “调用函数”">​</a></h3><p>在 Shell 中调用函数和调用其它命令是一模一样的。例如，如果你的函数名称为 <code>my_func</code>，你可以在命令行中像下面这样执行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ my_func</span></span></code></pre></div><p>如果你的函数接收多个参数，那么可以像下面这样写（类似命令行参数的使用）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ my_func arg1 arg2 arg3</span></span></code></pre></div><h3 id="定义函数" tabindex="-1">定义函数 <a class="header-anchor" href="#定义函数" aria-label="Permalink to “定义函数”">​</a></h3><p>我们可以用下面的语法去定义一个函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function function_name {</span></span>
<span class="line"><span>    Body of function</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>函数的主体可以包含任何有效的命令、循环语句和其它函数或脚本。现在让我们创建一个简单的函数，它向屏幕上显示一些消息（注：直接在命令行里写）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function print_msg {</span></span>
<span class="line"><span>    echo &quot;Hello, World&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在，让我们执行这个函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ print_msg</span></span>
<span class="line"><span>Hello, World</span></span></code></pre></div><p>不出所料，这个函数在屏幕上显示了一些消息。</p><p>在上面的例子中，我们直接在终端里创建了一个函数。这个函数也可以保存到文件中。如下面的例子所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>function print_msg {</span></span>
<span class="line"><span>    echo &quot;Hello, World&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>print_msg</span></span></code></pre></div><p>我们已经在 <code>function.sh</code> 文件中定义了这个函数。现在让我们执行这个脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x function.sh</span></span>
<span class="line"><span>$ ./function.sh</span></span>
<span class="line"><span>Hello, World</span></span></code></pre></div><p>你可以看到，上面的输出和之前的是一模一样的。</p><h3 id="更多函数用法" tabindex="-1">更多函数用法 <a class="header-anchor" href="#更多函数用法" aria-label="Permalink to “更多函数用法”">​</a></h3><p>在上一小节中我们定义了一个非常简单的函数。然而在软件开发的过程中，我们需要更多高级的函数，它可以接收多个参数并且带有返回值。在这一小节中，我们将讨论这种函数。</p><h4 id="向函数传递参数" tabindex="-1">向函数传递参数 <a class="header-anchor" href="#向函数传递参数" aria-label="Permalink to “向函数传递参数”">​</a></h4><p>我们可以像调用其它命令那样给函数提供参数。我们可以在函数里使用美元 <code>$</code> 符号访问到这些参数。例如，<code>$1</code> 表示第一个参数，<code>$2</code> 代表第二个参数，以此类推。</p><p>让我们修改下之前的函数，让它以参数的形式接收信息。修改后的函数就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function print_msg {</span></span>
<span class="line"><span>    echo &quot;Hello $1&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的函数中我们使用 <code>$1</code> 符号访问第一个参数。让我们执行这个函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ print_msg &quot;LinuxTechi&quot;</span></span></code></pre></div><p>执行完后，生成如下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Hello LinuxTechi</span></span></code></pre></div><h4 id="从函数中返回数值" tabindex="-1">从函数中返回数值 <a class="header-anchor" href="#从函数中返回数值" aria-label="Permalink to “从函数中返回数值”">​</a></h4><p>跟其它编程语言一样，Bash 提供了返回语句让我们可以向调用者返回一些数值。让我们举例说明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function func_return_value {</span></span>
<span class="line"><span>    return 10</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上面的函数向调用者返回 <code>10</code>。让我们执行这个函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ func_return_value</span></span>
<span class="line"><span>$ echo &quot;Value returned by function is: $?&quot;</span></span></code></pre></div><p>当你执行完，将会产生如下的输出结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Value returned by function is: 10</span></span></code></pre></div><p><strong>提示</strong>：在 Bash 中使用 <code>$?</code> 去获取函数的返回值。</p><h3 id="函数技巧" tabindex="-1">函数技巧 <a class="header-anchor" href="#函数技巧" aria-label="Permalink to “函数技巧”">​</a></h3><p>目前我们已经对 Bash 中的函数有了一些了解。现在让我们创建一些非常有用的 Bash 函数，它们可以让我们的生活变得更加轻松。</p><h4 id="logger" tabindex="-1">Logger <a class="header-anchor" href="#logger" aria-label="Permalink to “Logger”">​</a></h4><p>让我们创建一个 <code>logger</code> 函数，它可以输出带有日期和时间的 log 信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function log_msg {</span></span>
<span class="line"><span>    echo &quot;[\`date &#39;+ %F %T&#39;\` ]: $@&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>执行这个函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ log_msg &quot;This is sample log message&quot;</span></span></code></pre></div><p>执行完，就会生成如下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ 2018-08-16 19:56:34 ]: This is sample log message</span></span></code></pre></div><h4 id="显示系统信息" tabindex="-1">显示系统信息 <a class="header-anchor" href="#显示系统信息" aria-label="Permalink to “显示系统信息”">​</a></h4><p>让我们创建一个显示 GNU/Linux 信息的函数</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function system_info {</span></span>
<span class="line"><span>    echo &quot;### OS information ###&quot;</span></span>
<span class="line"><span>    lsb_release -a</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;### Processor information ###&quot;</span></span>
<span class="line"><span>    processor=\`grep -wc &quot;processor&quot; /proc/cpuinfo\`</span></span>
<span class="line"><span>    model=\`grep -w &quot;model name&quot; /proc/cpuinfo  | awk -F: &#39;{print $2}&#39;\`</span></span>
<span class="line"><span>    echo &quot;Processor = $processor&quot;</span></span>
<span class="line"><span>    echo &quot;Model     = $model&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    echo</span></span>
<span class="line"><span>    echo &quot;### Memory information ###&quot;</span></span>
<span class="line"><span>    total=\`grep -w &quot;MemTotal&quot; /proc/meminfo | awk &#39;{print $2}&#39;\`</span></span>
<span class="line"><span>    free=\`grep -w &quot;MemFree&quot; /proc/meminfo | awk &#39;{print $2}&#39;\`</span></span>
<span class="line"><span>    echo &quot;Total memory: $total kB&quot;</span></span>
<span class="line"><span>    echo &quot;Free memory : $free kB&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>执行完后会生成以下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### OS information ###</span></span>
<span class="line"><span>No LSB modules are available.</span></span>
<span class="line"><span>Distributor ID:           Ubuntu</span></span>
<span class="line"><span>Description:   Ubuntu 18.04.1 LTS</span></span>
<span class="line"><span>Release:         18.04</span></span>
<span class="line"><span>Codename:    bionic</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Processor information ###</span></span>
<span class="line"><span>Processor = 1</span></span>
<span class="line"><span>Model     =  Intel(R) Core(TM) i7-7700HQ CPU @ 2.80GHz</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Memory information ###</span></span>
<span class="line"><span>Total memory: 4015648 kB</span></span>
<span class="line"><span>Free memory : 2915428 kB</span></span></code></pre></div><h4 id="在当前目录下查找文件或者目录" tabindex="-1">在当前目录下查找文件或者目录 <a class="header-anchor" href="#在当前目录下查找文件或者目录" aria-label="Permalink to “在当前目录下查找文件或者目录”">​</a></h4><p>下面的函数从当前目录下查找文件或者目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function search {</span></span>
<span class="line"><span>    find . -name $1</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>让我们使用下面的命令查找 <code>dir4</code> 这个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ search dir4</span></span></code></pre></div><p>当你执行完命令后，将会产生如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./dir1/dir2/dir3/dir4</span></span></code></pre></div><h4 id="数字时钟" tabindex="-1">数字时钟 <a class="header-anchor" href="#数字时钟" aria-label="Permalink to “数字时钟”">​</a></h4><p>下面的函数在终端里创建了一个简单的数字时钟：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function digital_clock {</span></span>
<span class="line"><span>    clear</span></span>
<span class="line"><span>    while [ 1 ]</span></span>
<span class="line"><span>    do</span></span>
<span class="line"><span>        date +&#39;%T&#39;</span></span>
<span class="line"><span>        sleep 1</span></span>
<span class="line"><span>        clear</span></span>
<span class="line"><span>    done</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="函数库" tabindex="-1">函数库 <a class="header-anchor" href="#函数库" aria-label="Permalink to “函数库”">​</a></h3><p>库是函数的集合。将函数定义在文件里并在当前环境中导入那个文件，这样可以创建函数库。</p><p>假设我们已经在 <code>utils.sh</code> 中定义好了所有函数，接着在当前的环境下使用下面的命令导入函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source utils.sh</span></span></code></pre></div><p>之后你就可以像调用其它 Bash 命令那样执行库中任何的函数了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本文我们讨论了诸多可以提升效率的实用技巧。我希望这篇文章能够启发你去创造自己的技巧。</p><hr>`,72)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.linuxtechi.com/define-use-functions-linux-shell-script/"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/define-use-functions-linux-shell-script/",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(n,{href:"https://github.com/LuuMing"},{default:e(()=>[...s[4]||(s[4]=[a("LuuMing",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(n,{href:"https://github.com/pityonline"},{default:e(()=>[...s[5]||(s[5]=[a("pityonline",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=p(d,[["render",c]]);export{x as __pageData,C as default};
